use spacejam_core::safrole::ValidatorsData;

#[test]
fn validator_encoding() {
    let data = hex::decode("").unwrap();

    let mut validators = codec::decode::<ValidatorsData>(&data).unwrap();
    println!(
        "raw sorting: {:?}",
        validators
            .iter()
            .map(|v| hex::encode(v.ed25519))
            .collect::<Vec<_>>()
    );

    // sort by bandersnatch
    validators.sort_by_key(|v| v.bandersnatch);
    println!(
        "bandersnatch sorting: {:?}",
        validators
            .iter()
            .map(|v| hex::encode(v.ed25519))
            .collect::<Vec<_>>()
    );

    // sort by ed25519
    validators.sort_by_key(|v| v.ed25519);
    println!(
        "ed25519 sorting: {:?}",
        validators
            .iter()
            .map(|v| hex::encode(v.ed25519))
            .collect::<Vec<_>>()
    );
}
